import { GameObject, SaveData } from 'bare-engine';
import { ArcadeObject } from 'bare-engine/arcade';
import worldJson from '../public/data/world.json';

// WORLD LAYOUT, GENERATED BY scripts/buildWorld.cjs. EVERY ROOM SITS ON A GRID OF CELLS,
// ONE CELL BEING ONE SCREEN, SO A ROOM'S PLACE ON THE MAP IS ALSO ITS PLACE IN THE WORLD
export type Ability = "dash" | "double" | "wall" | "hammer";
export type ItemKind = Ability | "vial";

export interface RoomInfo
{
    id: string;
    name: string;
    area: string;
    x: number;
    y: number;
    w: number;
    h: number;
    shrine: boolean;
    boss: boolean;
    item: { id: string, kind: ItemKind } | null;
}

export interface LinkInfo
{
    a: string;
    b: string;
    x: number;
    y: number;
    dir: "left" | "right" | "up" | "down";
    gate: string;
}

export const TILE = worldJson.tile;
export const CELL_W = worldJson.cellWidth * TILE;
export const CELL_H = worldJson.cellHeight * TILE;
export const ROOMS = worldJson.rooms as RoomInfo[];
export const LINKS = worldJson.links as LinkInfo[];
export const AREAS = worldJson.areas as Record<string, { name: string, color: string }>;
export const START_ROOM = ROOMS.find(r => r.id == "h01")!.id;
export const START_HEALTH = 5;

export const ITEM_INFO: Record<ItemKind, { name: string, hint: string, texture: string }> = {
    dash:   { name: "Gale Elixir",     hint: "SHIFT or C to dash, also in the air", texture: "tile_0114" },
    double: { name: "Sky Elixir",      hint: "Jump again in mid-air",                texture: "tile_0116" },
    wall:   { name: "Gecko Ring",      hint: "Jump off walls, slide down them",      texture: "tile_0101" },
    hammer: { name: "Warhammer",       hint: "Attacks smash cracked stone (DOWN+X for floors)", texture: "tile_0117" },
    vial:   { name: "Heart Vial",      hint: "Maximum health up",                    texture: "tile_0115" },
};

const roomsById = new Map(ROOMS.map(room => [room.id, room]));

export function GetRoom(id: string): RoomInfo | undefined
{
    return roomsById.get(id);
}

// THE ROOM HOLDING A WORLD POSITION, IN PIXELS
export function GetRoomAt(worldX: number, worldY: number): RoomInfo | undefined
{
    var cx = Math.floor(worldX / CELL_W);
    var cy = Math.floor(worldY / CELL_H);
    return ROOMS.find(r => cx >= r.x && cx < r.x + r.w && cy >= r.y && cy < r.y + r.h);
}

// SAVE DATA
declare module 'bare-engine'
{
    namespace SaveData
    {
        let room: string;
        let shrineRoom: string;
        let abilities: Set<string>;
        let items: Set<string>;
        let visited: Set<string>;
        let maxHealth: number;
        let deaths: number;
        let playTime: number;
        let bossDefeated: boolean;
        let broken: Set<string>;
    }
}

export function SetSaveDefaults()
{
    bare.storage.SetDefaults({
        room: START_ROOM,
        shrineRoom: START_ROOM,
        abilities: new Set<string>(),
        items: new Set<string>(),
        visited: new Set<string>(),
        maxHealth: START_HEALTH,
        deaths: 0,
        playTime: 0,
        bossDefeated: false,
        broken: new Set<string>(),
    });
}

export function HasAbility(ability: Ability): boolean
{
    return SaveData.abilities.has(ability);
}

export function ItemsFound(): number
{
    return SaveData.items.size;
}

export const ITEM_TOTAL = ROOMS.filter(r => r.item).length;

// RECTANGLES OF THE CURRENT ROOM, FOR WALL CHECKS AND ENEMY LEDGE CHECKS.
// REBUILT AFTER EVERY ROOM LOAD FROM THE OBJECTS TAGGED solid AND oneway
export interface Rect { x: number, y: number, w: number, h: number }

export class RoomGeometry
{
    static solids: ArcadeObject[] = [];
    static oneways: ArcadeObject[] = [];

    static Collect(objects: GameObject[])
    {
        this.solids = [];
        this.oneways = [];
        for (var obj of objects)
        {
            if (!(obj instanceof ArcadeObject))
                continue;
            if (obj.tags.includes("solid"))
                this.solids.push(obj);
            else if (obj.tags.includes("oneway"))
                this.oneways.push(obj);
        }
    }

    static Remove(obj: ArcadeObject)
    {
        this.solids = this.solids.filter(o => o != obj);
    }

    static IsSolidAt(x: number, y: number, includeOneways: boolean = false): boolean
    {
        var hit = (o: ArcadeObject) => {
            var r = HitboxRect(o);
            return x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h;
        };
        return this.solids.some(hit) || (includeOneways && this.oneways.some(hit));
    }

    static Overlaps(rect: Rect): boolean
    {
        return this.solids.some(o => RectsOverlap(rect, HitboxRect(o)));
    }
}

// AN ARCADE OBJECT'S HITBOX IN WORLD SPACE
export function HitboxRect(obj: ArcadeObject): Rect
{
    var r = obj.physicsHitbox.rectangle;
    var sx = Math.abs(obj.scaleX), sy = Math.abs(obj.scaleY);
    return {
        x: obj.x + (r.x - obj.pivot.x) * sx,
        y: obj.y + (r.y - obj.pivot.y) * sy,
        w: r.width * sx,
        h: r.height * sy,
    };
}

export function RectsOverlap(a: Rect, b: Rect): boolean
{
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
